'use client';

import { createField } from '@dawitlabs/pixelfield';
import { useEffect, useRef } from 'react';

export interface FogProps {
  className?: string;
  tint?: string;
  seed?: number;
  interactive?: boolean;
}

export function Fog({ className, tint, seed = 0, interactive = true }: FogProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const field = createField(canvas, {
      generator: 'noise',
      falloff: 'fill',
      scale: 0.55,
      aspect: 0.5,
      warp: 0.5,
      contrast: 0.6,
      mode: 'fbm',
      speed: 0.45,
      intensity: 0.85,
      flow: { x: 6, y: 0 },
      seed,
      tint,
      interactive,
    });
    return () => field.destroy();
  }, [tint, seed, interactive]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}

import { createField } from '@dawitlabs/pixelfield';

export function mountFog(canvas, { tint, seed = 0, interactive = true } = {}) {
  return createField(canvas, {
      generator: 'noise',
      falloff: 'fill',
      scale: 0.55,
      aspect: 0.5,
      warp: 0.5,
      contrast: 0.6,
      mode: 'fbm',
      speed: 0.45,
      intensity: 0.85,
      flow: { x: 6, y: 0 },
    seed,
    tint,
    interactive,
  });
}
